import{_ as n,o as e,c as i,a2 as r}from"./chunks/framework.CCtxZRER.js";const m=JSON.parse('{"title":"SOP Penerimaan Barang","description":"Langkah menerima barang dari vendor sampai barang tersimpan di rak dan tercatat.","frontmatter":{"title":"SOP Penerimaan Barang","description":"Langkah menerima barang dari vendor sampai barang tersimpan di rak dan tercatat.","status":"ditinjau","dasar":"alur barang masuk Gudang Teknik","nomor_dokumen":null,"versi":0.2,"pemilik":"Gudang Teknik","pengesah":null,"diperbarui":"2026-10-13T00:00:00.000Z","kategori":"SOP","sumber":["ppt-gudang-teknik","catatan-alur"],"kata_kunci":["SOP","penerimaan barang","receiving","barang masuk","vendor","surat tanda terima","database","OS/PPIC","rak","catatan manual","dikembalikan"]},"headers":[],"relativePath":"sop/penerimaan-barang.md","filePath":"sop/penerimaan-barang.md"}'),t={name:"sop/penerimaan-barang.md"};function l(s,a,d,k,u,g){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="sop-penerimaan-barang" tabindex="-1">SOP Penerimaan Barang <a class="header-anchor" href="#sop-penerimaan-barang" aria-label="Permalink to &quot;SOP Penerimaan Barang&quot;">​</a></h1><p class="lead">Dipakai setiap kali vendor atau supplier mengantar barang ke Gudang Teknik.</p><h2 id="tujuan" tabindex="-1">Tujuan <a class="header-anchor" href="#tujuan" aria-label="Permalink to &quot;Tujuan&quot;">​</a></h2><p>Memastikan barang yang diterima sesuai pesanan, kondisinya baik, jumlahnya lengkap, lalu tersimpan dan tercatat dengan benar.</p><h2 id="yang-perlu-disiapkan" tabindex="-1">Yang perlu disiapkan <a class="header-anchor" href="#yang-perlu-disiapkan" aria-label="Permalink to &quot;Yang perlu disiapkan&quot;">​</a></h2><ul><li>Data pesanan barang yang akan datang.</li><li>Surat tanda terima.</li><li>Akses ke database barang.</li><li>APD sesuai arahan pembimbing.</li></ul><h2 id="langkah-langkah" tabindex="-1">Langkah-langkah <a class="header-anchor" href="#langkah-langkah" aria-label="Permalink to &quot;Langkah-langkah&quot;">​</a></h2><ol><li><strong>Cek kesesuaian pesanan.</strong> Saat barang datang, cocokkan barang dengan pesanan. Kalau tidak sesuai, barang dikembalikan ke vendor.</li><li><strong>Bawa barang masuk</strong> ke dalam gudang, lalu terima barangnya.</li><li><strong>Cek kondisi dan jumlah.</strong> Kalau kondisinya buruk atau jumlahnya kurang dari pesanan, barang dikembalikan ke vendor.</li><li><strong>Berikan surat tanda terima</strong> yang sudah ditandatangani kepada vendor.</li><li><strong>Input ke database</strong>: jumlah, jenis barang, tipe barang, dan tanggal masuk.</li><li><strong>Kirim laporan ke divisi OS/PPIC</strong> bahwa barang sudah masuk dan sesuai.</li><li><strong>Simpan barang di rak</strong> sesuai lokasi yang tercatat di database.</li><li><strong>Isi catatan manual di rak</strong> tempat barang disimpan.</li></ol><p>Flowchart-nya ada di <a href="/WareHouse/alur-kerja/barang-masuk">Alur Barang Masuk</a>.</p><h2 id="cek-sebelum-selesai" tabindex="-1">Cek sebelum selesai <a class="header-anchor" href="#cek-sebelum-selesai" aria-label="Permalink to &quot;Cek sebelum selesai&quot;">​</a></h2><ul class="daftar-periksa"><li>Barang sesuai pesanan.</li><li>Kondisi baik dan jumlah lengkap.</li><li>Surat tanda terima sudah diberikan ke vendor.</li><li>Data sudah masuk database.</li><li>Laporan sudah dikirim ke OS/PPIC.</li><li>Barang ada di rak yang benar.</li><li>Catatan manual di rak sudah diisi.</li></ul><h2 id="perhatian-keselamatan" tabindex="-1">Perhatian keselamatan <a class="header-anchor" href="#perhatian-keselamatan" aria-label="Permalink to &quot;Perhatian keselamatan&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Saat membongkar dan membawa barang</p><ul><li>Cek berat barang sebelum mengangkat. Minta bantuan atau pakai alat angkut untuk barang berat.</li><li>Alat angkut bermesin hanya boleh dipakai oleh orang yang berwenang.</li><li>Pakai sarung tangan saat membuka kemasan yang tajam atau diikat strapping.</li></ul></div>',13)])])}const b=n(t,[["render",l]]);export{m as __pageData,b as default};
